s='777b624ec45a40d086a880b5f15cdcd0'; d=Path('mask/ml/privacy_v1/annotation/shards')/s
records=[]; notes=[]
def add(slug,text,task,entities,decisions,facts,variant='a'):
    es=[dict(id='m'+str(i+1),entity_id=e[0],label=e[1],quote=e[2]) for i,e in enumerate(entities)]
    ds=[]; output=text
    for item in decisions:
        if item[0]=='section':
            _,q,label,reason=item; x=dict(kind='section',quote=q,label=label,action='DROP',relevance='unnecessary',reason=reason); replacement=''
        else:
            idx,action,rel,*rest=item; e=es[idx]; x=dict(kind='entity',target_id=e['id'],entity_id=e['entity_id'],quote=e['quote'],label=e['label'],action=action,relevance=rel)
            if rest: x['reason']=rest[0]
            replacement={'ALIAS':'[PERSON_1]','PLACEHOLDER':'['+e['label']+']','KEEP':e['quote']}[action]
        ds.append(x)
        if x['action']!='KEEP': output=output.replace(x['quote'],replacement,1)
    prefix=s+':'+slug
    rec=dict(schema_version=2,shard_id=s,id=prefix+'-'+variant,family_id=prefix+'-family',persona_id=prefix+'-persona',source_id=prefix+'-source',template_id=prefix+'-template',split='train',language='en',input_kind='message',text=text,task=task,entities=es,decisions=ds,required_facts=[{'quote':f} for f in facts],approved_output=output,provenance=dict(synthetic=True,human_audited=False,generator_model='gpt-6.1-terra',generator_id=s+':generator'),review={'status':'pending'})
    records.append(rec); notes.append(dict(record_id=rec['id'],dependencies=[dict(claim='Preserve the following task-relevant source claim or constraint.',supporting_quotes=[f],disclosure_limit='Permitted as written.') for f in facts]+[dict(claim='Protected values may be unavailable for exact analysis.',supporting_quotes=[x['quote']],disclosure_limit=x.get('reason','Private person name is aliased.')) for x in ds if x['action'] in ('ALIAS','PLACEHOLDER')]))
